(async()=>{
  const E=__echoes, st=()=>E.state();
  const raf=()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
  const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  const ally=(c)=>st().party.find(p=>p.classId===c);
  async function aimAt(tx,tz){let sx=800,sy=450;for(let i=0;i<16;i++){window.dispatchEvent(new MouseEvent('mousemove',{clientX:sx,clientY:sy,bubbles:true}));await raf();const a=st().party[0].aim;if(!a){sx+=5;continue;}const ex=tx-a.x,ez=tz-a.z;if(Math.hypot(ex,ez)<0.02)break;sx+=ex*84.5;sy+=ez*57;}return st().party[0].aim;}
  function press(code){window.dispatchEvent(new KeyboardEvent('keydown',{code,bubbles:true}));window.dispatchEvent(new KeyboardEvent('keyup',{code,bubbles:true}));}
  const out={};
  E.cmd('setHp',2,0); E.cmd('setHp',3,0);
  E.cmd('grantNode','siphon');
  out.socketSiphon=E.cmd('socket','mending_bolt','siphon');
  async function cast(label){
    E.cmd('killAllEnemies');
    E.cmd('setHp',1,0.2);
    await raf();
    const t=ally('tank');
    const L=Math.hypot(t.x,t.z);
    const dx=t.x-1.4*t.x/L, dz=t.z-1.4*t.z/L;
    const did=E.cmd('spawn','dummy',dx,dz);
    const aim=await aimAt(t.x,t.z);
    const t0=E.tick;
    press('Digit1');
    await sleep(1100);
    const ev=E.events.filter(e=>e.tick>=t0&&['heal','siphon_drain','siphon_fizzle','hit','skill_cast'].includes(e.type));
    out[label]={dummy:did,aim,tank:{x:t.x,z:t.z},dpos:{dx,dz},resolved:E.cmd('buildView').skills.find(s=>s.id==='mending_bolt').resolved,ev};
  }
  await cast('A_siphon_only');
  E.cmd('grantNode','sharpen');
  out.socketSharpen=E.cmd('socket','mending_bolt','sharpen');
  await sleep(2700);
  await cast('B_siphon_sharpen');
  out.unsocket=E.cmd('unsocket','mending_bolt',1);
  E.cmd('grantNode','ascend');
  out.socketAscend=E.cmd('socket','mending_bolt','ascend');
  await sleep(2700);
  await cast('C_siphon_ascend');
  return JSON.stringify(out);
})()
